	(2)\,\,\,\,\,\,\,\,\,\, |\varepsilon| &\geq \frac{|k|}{2\sqrt{n^2d-k}+\frac{1}{2}} \geq \frac{|k|}
	{2\sqrt{n^2d+|k|}+\frac{1}{2}}
